using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Reflection;using System.Windows.Forms;using ScreenDock;
class InlineLayoutTests {
 static object F(object f,string name){return typeof(MainForm).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);}static void Check(bool x,string m){if(!x)throw new Exception(m);}static void Pump(){var end=DateTime.UtcNow.AddMilliseconds(100);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(5);}}
 [STAThread]static void Main(){Application.EnableVisualStyles();UiZoom.Percent=100;using(var f=new MainForm(true)){f.Show();Pump();var map=(Map)F(f,"map");var list=(ListBox)F(f,"list");var res=(ComboBox)F(f,"layoutResolution");var rate=(ComboBox)F(f,"layoutRate");Check(map.DragEnabled&&res.Visible&&rate.Items.Count>0,"homepage editing missing");using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(System.IO.Path.Combine(System.IO.Path.GetTempPath(),"ScreenDock-home-v25.png"));}var preview=(List<Display>)F(f,"layoutPreview");var actual=(List<Display>)F(f,"displays");var mode=preview[1].Mode;mode.x=2560;mode.y=0;preview[1].Mode=mode;map.Changed();list.SelectedIndex=1;Check((bool)F(f,"layoutDirty"),"selection discarded changes");Check(actual[1].Mode.y==180,"preview mutated actual");typeof(MainForm).GetMethod("ReloadInlineLayout",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f,null);Check(((List<Display>)F(f,"layoutPreview"))[1].Mode.y==0,"refresh discarded preview");((Button)F(f,"layoutReset")).PerformClick();Check(!(bool)F(f,"layoutDirty")&&((List<Display>)F(f,"layoutPreview"))[1].Mode.y==180,"reset failed");var direction=(ComboBox)F(f,"layoutOrientation");var primary=(Button)F(f,"layoutPrimary");preview=(List<Display>)F(f,"layoutPreview");direction.SelectedIndex=1;Check(preview[1].Mode.width==1080&&preview[1].Mode.height==1920&&preview[1].Mode.orientation==1,"portrait dimensions wrong");Check((string)res.SelectedItem=="1080 × 1920","portrait resolution choices stale");primary.PerformClick();Check(preview[1].Primary&&!preview[0].Primary&&actual[0].Primary,"primary preview isolation failed");var plan=DisplayLayout.Plan(preview);Check(plan[preview[1].Device].x==0&&plan[preview[1].Device].y==0,"new primary not normalized");direction.SelectedIndex=3;Check(preview[1].Mode.width==1080&&preview[1].Mode.orientation==3,"flipped portrait wrong");direction.SelectedIndex=2;Check(preview[1].Mode.width==1920&&preview[1].Mode.height==1080,"landscape restoration wrong");((Button)F(f,"layoutReset")).PerformClick();preview=(List<Display>)F(f,"layoutPreview");Check(preview[0].Primary&&preview[1].Mode.orientation==0&&direction.SelectedIndex==0&&(string)res.SelectedItem=="1920 × 1080","rotation/primary reset failed");Check(direction.Top>res.Top&&direction.Bottom<((Label)F(f,"layoutHint")).Top,"direction row overlap");f.ClientSize=new Size(1500,1000);Pump();Check(res.Top>=map.Bottom,"resize overlap");using(var shortcuts=new ToolStripMenuItem()){typeof(MainForm).GetMethod("FillPresets",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f,new object[]{shortcuts,true});var choices=shortcuts.DropDownItems.OfType<ToolStripMenuItem>().Where(x=>x.ToolTipText=="点击应用此预设").ToList();foreach(var choice in choices){Check(choice.DropDownItems.Count==0,"tray preset still requires nested Apply");choice.PerformClick();Pump();Check(((Label)F(f,"status")).Text.Contains("已收到预设切换操作"),"tray preset click did not dispatch");}}var trayMenu=(ContextMenuStrip)F(f,"trayMenu");var showMenu=typeof(MainForm).GetMethod("ShowTrayMenu",BindingFlags.NonPublic|BindingFlags.Instance);Check(((NotifyIcon)F(f,"tray")).ContextMenuStrip==null,"automatic tray positioning still enabled");foreach(var screen in Screen.AllScreens){var area=screen.WorkingArea;foreach(var anchor in new[]{new Point(area.Right-25,area.Bottom-5),new Point(area.Left+25,area.Top+5)}){for(int attempt=0;attempt<2;attempt++){showMenu.Invoke(f,new object[]{anchor});Pump();Check(trayMenu.Visible,"tray menu requires second click");Check(area.Contains(trayMenu.Bounds),"tray menu outside clicked monitor");Check(trayMenu.Bounds.Left<=anchor.X+2&&trayMenu.Bounds.Right>=anchor.X-2,"tray menu detached horizontally");Check(Math.Min(Math.Abs(trayMenu.Top-anchor.Y),Math.Abs(trayMenu.Bottom-anchor.Y))<10,"tray menu detached vertically");trayMenu.Close();Pump();}}}var modes=(Dictionary<string,List<Native.Mode>>)F(f,"layoutModes");var rememberedModes=modes[actual[0].Device];typeof(MainForm).GetMethod("ReloadInlineLayout",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f,null);Check(Object.ReferenceEquals(rememberedModes,modes[actual[0].Device]),"unchanged refresh enumerated modes again");f.ClientSize=new Size(800,570);Pump();var viewport=f.Controls.OfType<Panel>().First();viewport.AutoScrollPosition=new Point(0,300);Pump();Check(f.MainMenuStrip.Parent==f&&f.MainMenuStrip.Top==0&&f.MainMenuStrip.Visible,"menu scrolled out of small window");f.ClientSize=new Size(1500,1000);Pump();Check(Application.OpenForms.Count==1,"unexpected editor window");}Console.WriteLine("PASS: inline controls, independent preview, selection/refresh preserve edits, reset, resize spacing; no editor dialog or hardware changes.");}
}
